package com.novara.banking.statement;

import com.lowagie.text.*;
import com.lowagie.text.pdf.*;
import com.novara.banking.statement.StatementModels.*;
import org.springframework.stereotype.Service;
import java.awt.Color;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.charset.Charset;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

@Service public class StatementExportService {
 private static final DateTimeFormatter WHEN=DateTimeFormatter.ofPattern("dd MMM yyyy HH:mm z",Locale.ENGLISH).withZone(ZoneId.of("Asia/Kolkata"));
 public byte[] statementPdf(StatementService.Snapshot snap){ensurePdfText(snap.customerName(),snap.summary().maskedNumber());snap.entries().forEach(e->ensurePdfText(e.description(),e.reference()));try(var out=new ByteArrayOutputStream()){Document doc=new Document(PageSize.A4.rotate(),30,30,36,36);PdfWriter writer=PdfWriter.getInstance(doc,out);writer.setPageEvent(new PageNumbers());doc.addTitle("Novara Bank Account Statement");doc.addAuthor("Novara Bank Sandbox");doc.open();title(doc,"NOVARA BANK","Account Statement");var s=snap.summary();doc.add(new Paragraph("Customer: "+snap.customerName()+"    Account: "+s.maskedNumber()+"    Type: "+s.accountType()+"    Currency: "+s.currency()));doc.add(new Paragraph("Period: "+s.from()+" to "+s.to()+"    Accounting cutoff: "+WHEN.format(s.cutoff())));doc.add(Chunk.NEWLINE);PdfPTable totals=new PdfPTable(4);totals.setWidthPercentage(100);cell(totals,"Opening\n"+money(s.openingBalanceMinor()));cell(totals,"Money in\n"+money(s.totalCreditMinor()));cell(totals,"Money out\n"+money(s.totalDebitMinor()));cell(totals,"Closing\n"+money(s.closingBalanceMinor()));doc.add(totals);doc.add(Chunk.NEWLINE);PdfPTable table=new PdfPTable(new float[]{1.2f,3.5f,2f,1.4f,1.4f,1.5f});table.setWidthPercentage(100);table.setHeaderRows(1);for(String h:new String[]{"Date","Description","Reference","Debit","Credit","Balance"})header(table,h);for(Entry e:snap.entries().reversed()){cell(table,e.valueDate().toString());cell(table,e.description());cell(table,e.reference());cell(table,e.debitMinor()==0?"":money(e.debitMinor()));cell(table,e.creditMinor()==0?"":money(e.creditMinor()));cell(table,money(e.runningBalanceMinor()));}doc.add(table);doc.add(Chunk.NEWLINE);doc.add(new Paragraph("Statement reference: STM-"+snap.id().toString().substring(0,8).toUpperCase(Locale.ROOT)+". Fictional sandbox banking environment. Generated from posted ledger entries."));doc.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Unable to render statement PDF",e);}}
 public byte[] receiptPdf(Receipt r){ensurePdfText(r.reference(),r.description(),r.debitAccountMask(),r.creditAccountMask());try(var out=new ByteArrayOutputStream()){Document doc=new Document(PageSize.A5,36,36,42,42);PdfWriter writer=PdfWriter.getInstance(doc,out);writer.setPageEvent(new PageNumbers());doc.addTitle("Novara Bank Transaction Receipt");doc.addAuthor("Novara Bank Sandbox");doc.open();title(doc,"NOVARA BANK","Transaction Receipt");doc.add(new Paragraph("COMPLETED",new Font(Font.HELVETICA,11,Font.BOLD,new Color(24,112,72))));doc.add(new Paragraph("INR "+money(r.amountMinor()),new Font(Font.HELVETICA,24,Font.BOLD,new Color(7,29,49))));doc.add(Chunk.NEWLINE);PdfPTable details=new PdfPTable(2);details.setWidthPercentage(100);pair(details,"Reference",r.reference());pair(details,"Date and time",WHEN.format(r.postedAt()));pair(details,"Type",r.type());pair(details,"Description",r.description());if(r.debitAccountMask()!=null)pair(details,"From account",r.debitAccountMask());if(r.creditAccountMask()!=null)pair(details,"To account",r.creditAccountMask());doc.add(details);doc.add(Chunk.NEWLINE);doc.add(new Paragraph("Generated from a committed Novara ledger posting. Fictional sandbox banking environment."));doc.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Unable to render receipt PDF",e);}}
 public byte[] csv(StatementService.Snapshot snap){StringBuilder b=new StringBuilder("Date,Description,Transaction Reference,Debit,Credit,Running Balance,Currency\r\n");for(Entry e:snap.entries().reversed())b.append(csv(e.valueDate().toString())).append(',').append(csv(e.description())).append(',').append(csv(e.reference())).append(',').append(e.debitMinor()).append(',').append(e.creditMinor()).append(',').append(e.runningBalanceMinor()).append(',').append(e.currency()).append("\r\n");return ("\uFEFF"+b).getBytes(StandardCharsets.UTF_8);}
 static String csv(String raw){String value=raw==null?"":raw;String check=value.stripLeading();if(!check.isEmpty()&&"=+-@\t\r".indexOf(check.charAt(0))>=0)value="'"+value;return '"'+value.replace("\"","\"\"")+'"';}
 private void title(Document d,String brand,String name)throws DocumentException{d.add(new Paragraph(brand,new Font(Font.HELVETICA,11,Font.BOLD,new Color(181,138,40))));d.add(new Paragraph(name,new Font(Font.HELVETICA,22,Font.BOLD,new Color(7,29,49))));d.add(Chunk.NEWLINE);}private void header(PdfPTable t,String v){PdfPCell c=new PdfPCell(new Phrase(v,new Font(Font.HELVETICA,9,Font.BOLD,Color.WHITE)));c.setBackgroundColor(new Color(7,49,75));c.setPadding(6);t.addCell(c);}private void cell(PdfPTable t,String v){PdfPCell c=new PdfPCell(new Phrase(v,new Font(Font.HELVETICA,8)));c.setPadding(5);t.addCell(c);}private void pair(PdfPTable t,String k,String v){cell(t,k);cell(t,v);}private String money(long minor){return String.format(Locale.ENGLISH,"%,d.%02d",minor/100,Math.abs(minor%100));}
 private void ensurePdfText(String... values){var encoder=Charset.forName("windows-1252").newEncoder();for(String value:values)if(value!=null&&!encoder.canEncode(value))throw new com.novara.banking.shared.DomainException(org.springframework.http.HttpStatus.UNPROCESSABLE_ENTITY,"PDF_UNSUPPORTED_CHARACTERS","This document contains characters that the approved PDF font cannot render safely.");}
 private static final class PageNumbers extends PdfPageEventHelper{public void onEndPage(PdfWriter writer,Document document){ColumnText.showTextAligned(writer.getDirectContent(),Element.ALIGN_CENTER,new Phrase("Page "+writer.getPageNumber(),new Font(Font.HELVETICA,8,Font.NORMAL,Color.GRAY)),(document.right()+document.left())/2,document.bottom()-18,0);}}
}
